  var GIFT_PAPER = [["#5fb9de", "#f6c945"], ["#f28fb1", "#ffffff"], ["#7cc35a", "#e8584e"], ["#b99cf0", "#f6c945"], ["#ff9f5a", "#5fb9de"]];
