      const now0 = this._planNow();
      const doze = this._dbgDoze ? [now0 + 2500, now0 + 14e3] : h >= 13 && h < 17 && S.r(3) < 0.35 ? [S.end - 4e4, S.end - 3e4 + S.r(4) * 8e3] : null;
