      const snow = kind === "s";
      const K2 = snow ? 2 : 1;
      const u = (i, j, a, b) => a + seeded(K2, i, j) * (b - a);
      const twice = (y, style) => `<i class="${kind}" style="top:${y.toFixed(1)}%;${style}"></i><i class="${kind}" style="top:${(y + 50).toFixed(1)}%;${style}"></i>`;
